dashboard.definition:
{
  "title": "Service Health",
  "description": "Which production service is degraded?",
  "dataSources": {
    "ds_heartbeat": {
      "type": "ds.search",
      "name": "Generator heartbeat age",
      "options": {
        "query": "| inputlookup kiruna_asset_latest\n| stats max(last_seen) as t\n| eval age_s=if(isnull(t), 99999, round(now()-t)), band=if(age_s<=180, 3, 1)\n| eval label=if(age_s<=180, \"Alive \".age_s.\" s\", \"Stale \".age_s.\" s\")\n| fields label band",
        "refresh": "60s",
        "refreshType": "delay"
      }
    },
    "ds_scores": {
      "type": "ds.search",
      "name": "Service scores (summary lookup)",
      "options": {
        "query": "| inputlookup kiruna_service_scores\n| sort 0 service_order\n| eval _color_rank=color_rank\n| table service score band reason drilldown_view _color_rank",
        "refresh": "60s",
        "refreshType": "delay"
      }
    },
    "ds_parent": {
      "type": "ds.chain",
      "name": "Parent score",
      "options": {
        "extend": "ds_scores",
        "query": "| where service=\"Kiruna production\"\n| eval label=score.\" \".band\n| table label score"
      }
    },
    "ds_children": {
      "type": "ds.chain",
      "name": "Child scores",
      "options": {
        "extend": "ds_scores",
        "query": "| where service!=\"Kiruna production\"\n| table service score"
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Service Health\nWhich production service is degraded?  \nSynthetic, illustrative demo data. Scenario clock is time-compressed. Not LKAB production data.",
        "fontColor": "#E1E6EB"
      }
    },
    "viz_heartbeat": {
      "type": "splunk.singlevalue",
      "title": "Generator heartbeat",
      "dataSources": {
        "primary": "ds_heartbeat"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"label\") | lastPoint()",
        "backgroundColor": "#1E2128",
        "majorColor": "> primary | seriesByName(\"band\") | lastPoint() | rangeValue(bandColors)",
        "underLabel": "Since last tick. Stale means the generator stopped."
      },
      "context": {
        "bandColors": [
          {
            "to": 2,
            "value": "#D93F3C"
          },
          {
            "from": 2,
            "value": "#65A637"
          }
        ]
      }
    },
    "viz_kpi_bg": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1E2128",
        "strokeColor": "#3D4456",
        "cornerRadius": 6
      }
    },
    "viz_parent": {
      "type": "splunk.singlevalue",
      "title": "Kiruna production (parent)",
      "dataSources": {
        "primary": "ds_parent"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"label\") | lastPoint()",
        "backgroundColor": "#1E2128",
        "majorColor": "> primary | seriesByName(\"score\") | lastPoint() | rangeValue(bandColors)",
        "underLabel": "80-100 Healthy, 50-79 Warning, 0-49 Critical. Demo score."
      },
      "context": {
        "bandColors": [
          {
            "to": 50,
            "value": "#D93F3C"
          },
          {
            "from": 50,
            "to": 80,
            "value": "#F5A623"
          },
          {
            "from": 80,
            "value": "#65A637"
          }
        ]
      }
    },
    "viz_children": {
      "type": "splunk.bar",
      "title": "Child service scores (demo fixture bands)",
      "dataSources": {
        "primary": "ds_children"
      },
      "options": {
        "backgroundColor": "#1E2128",
        "legendDisplay": "off",
        "seriesColors": [
          "#5C9BD6"
        ],
        "xAxisTitleText": "",
        "yAxisMax": 100
      }
    },
    "viz_scores": {
      "type": "splunk.table",
      "title": "Services (click to open the related view)",
      "dataSources": {
        "primary": "ds_scores"
      },
      "options": {
        "count": 10,
        "showInternalFields": false,
        "backgroundColor": "#1E2128",
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        }
      },
      "context": {
        "rowColors": [
          {
            "to": 1.5,
            "value": "#5A2A2A"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#5A4A22"
          },
          {
            "from": 2.5,
            "value": "#1E2128"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/lkab_kiruna_demo/$row.drilldown_view.value|u$",
            "newTab": false
          }
        }
      ]
    },
    "viz_deps": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "**Dependency (top to bottom).** Kiruna production depends on Draw and load, Level haulage, Crushing, Hoisting, and Autonomy and comms. Outbound logistics depends on Hoisting and is lagged; it is not an input to the parent minimum. One stuck truck alone does not pull production down.  \nWhen ITSI is installed, continue in Service Analyzer. This table is the demo score.",
        "fontColor": "#E1E6EB"
      }
    }
  },
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-8h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1440,
          "height": 880,
          "display": "auto-scale",
          "backgroundColor": "#1A1C20"
        },
        "structure": [
          {
            "item": "viz_header",
            "type": "block",
            "position": {
              "x": 20,
              "y": 10,
              "w": 1000,
              "h": 90
            }
          },
          {
            "item": "viz_heartbeat",
            "type": "block",
            "position": {
              "x": 1040,
              "y": 10,
              "w": 380,
              "h": 90
            }
          },
          {
            "item": "viz_kpi_bg",
            "type": "block",
            "position": {
              "x": 20,
              "y": 110,
              "w": 460,
              "h": 280
            }
          },
          {
            "item": "viz_parent",
            "type": "block",
            "position": {
              "x": 30,
              "y": 120,
              "w": 440,
              "h": 260
            }
          },
          {
            "item": "viz_children",
            "type": "block",
            "position": {
              "x": 500,
              "y": 110,
              "w": 920,
              "h": 280
            }
          },
          {
            "item": "viz_scores",
            "type": "block",
            "position": {
              "x": 20,
              "y": 410,
              "w": 1400,
              "h": 320
            }
          },
          {
            "item": "viz_deps",
            "type": "block",
            "position": {
              "x": 20,
              "y": 750,
              "w": 1400,
              "h": 110
            }
          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Services",
          "layoutId": "layout_1"
        }
      ],
      "options": {
        "showTabBar": false
      }
    }
  },
  "applicationProperties": {
    "theme": "dark"
  }
}
